RENDERED = {}

def render_svg(svg_data):
    byte_array = QByteArray(svg_data.encode("utf-8"))
    renderer = QSvgRenderer(byte_array)

    # Create a QPixmap to render into
    size = QSize(100, 100)
    pixmap = QPixmap(size)
    pixmap.fill(Qt.transparent)  # make background transparent

    # Render SVG onto the pixmap
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()

    return pixmap

def get(name, backup=None):
    """this function created so we only render SVG when needed, avoid crashing when qApp not initialized yet"""
    if name not in RENDERED:
        if name not in LIBRARY:
            if backup: name = backup
            else: name = "broken image"
        RENDERED[name] = render_svg(LIBRARY[name]).toImage()
        return RENDERED[name]
    return RENDERED[name]